('bmlt-urinalysis-bodyfluids1-practice-001','BMLT','BMLT NHPC Licensing','mcq','free',1,'{"question":"The normal colour of freshly passed urine is usually:","translation":"","options":["Pale yellow to amber","Blue","Milky white","Black"],"correctIndex":0,"explanation":"सामान्य ताजा पिसाब हल्का पहेँलोदेखि amber रङको हुन्छ।","explanationNe":"सामान्य ताजा पिसाब हल्का पहेँलोदेखि amber रङको हुन्छ।","topic":"Urinalysis & Body Fluids"}'::jsonb,true),
('bmlt-urinalysis-bodyfluids1-practice-002','BMLT','BMLT NHPC Licensing','mcq','free',2,'{"question":"The normal pH range of urine is approximately:","translation":"","options":["4.5–8.0","1.0–2.0","9.5–12.0","Exactly 7.0"],"correctIndex":0,"explanation":"पिसाबको pH सामान्यतया करिब 4.5–8.0 को दायरामा हुन सक्छ।","explanationNe":"पिसाबको pH सामान्यतया करिब 4.5–8.0 को दायरामा हुन सक्छ।","topic":"Urinalysis & Body Fluids"}'::jsonb,true),
